#define CK(x) do{auto e=(x);if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}while(0)
struct Device{double *rs,*rp,*s,*p;std::vector<double>is,ip;};
void launch(const RLCase&c,Device&d,double t){k_forward_rush_larsen<<<(c.n+255)/256,256>>>(d.s,t,c.dt,d.p,c.n);CK(cudaGetLastError());}
void number(std::ofstream&f,double x){f.write((char*)&x,8);}void values(std::ofstream&f,const std::vector<double>&a){f.write((char*)a.data(),a.size()*8);}
int main(){try{auto cs=rlcases(RL_ROOT,false);std::vector<Device>ds;for(auto&c:cs){Device d;d.is=rlexpand(c.s,19,c.n,c.np);d.ip=rlexpand(c.p,53,c.n,c.np);CK(cudaMalloc(&d.rs,(d.is.size()+128)*8));CK(cudaMalloc(&d.rp,(d.ip.size()+128)*8));d.s=d.rs+64;d.p=d.rp+64;ds.push_back(d);}auto reset=[&](size_t k){auto&d=ds[k];std::vector<double>s(d.is.size()+128,-777),p(d.ip.size()+128,-777);std::copy(d.is.begin(),d.is.end(),s.begin()+64);std::copy(d.ip.begin(),d.ip.end(),p.begin()+64);CK(cudaMemcpy(d.rs,s.data(),s.size()*8,cudaMemcpyHostToDevice));CK(cudaMemcpy(d.rp,p.data(),p.size()*8,cudaMemcpyHostToDevice));};for(size_t k=0;k<cs.size();k++){reset(k);launch(cs[k],ds[k],cs[k].t);CK(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){std::string path="trial"+std::to_string(trial)+".bin";std::ofstream out(path,std::ios::binary);number(out,3);for(size_t k=0;k<cs.size();k++){auto&c=cs[k];auto&d=ds[k];reset(k);CK(cudaDeviceSynchronize());number(out,c.n);number(out,c.steps);number(out,c.np);number(out,c.t);number(out,c.dt);std::vector<double>s(d.is.size()),p(d.ip.size());CK(cudaMemcpy(s.data(),d.s,s.size()*8,cudaMemcpyDeviceToHost));CK(cudaMemcpy(p.data(),d.p,p.size()*8,cudaMemcpyDeviceToHost));values(out,s);values(out,p);}double sec=0;for(size_t k=0;k<cs.size();k++){auto&c=cs[k];auto&d=ds[k];double t=c.t;CK(cudaDeviceSynchronize());auto st=std::chrono::steady_clock::now();for(unsigned step=0;step<c.steps;step++){launch(c,d,t);t+=c.dt;}CK(cudaDeviceSynchronize());sec+=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count();std::vector<double>s(d.is.size()),params(d.ip.size());CK(cudaMemcpy(s.data(),d.s,s.size()*8,cudaMemcpyDeviceToHost));CK(cudaMemcpy(params.data(),d.p,params.size()*8,cudaMemcpyDeviceToHost));if(std::memcmp(params.data(),d.ip.data(),params.size()*8))throw std::runtime_error("parametersmutated");values(out,s);CK(cudaMemcpy(d.s,d.is.data(),d.is.size()*8,cudaMemcpyHostToDevice));launch(c,d,c.t);CK(cudaDeviceSynchronize());CK(cudaMemcpy(s.data(),d.s,s.size()*8,cudaMemcpyDeviceToHost));values(out,s);for(auto pair:{std::make_pair(d.rs,d.is.size()),std::make_pair(d.rp,d.ip.size())}){std::vector<double>g(128);CK(cudaMemcpy(g.data(),pair.first,64*8,cudaMemcpyDeviceToHost));CK(cudaMemcpy(g.data()+64,pair.first+64+pair.second,64*8,cudaMemcpyDeviceToHost));values(out,g);}}out.close();if(!out)throw std::runtime_error("artifactwrite");double metrics[3];if(study_check(path.c_str(),metrics))throw std::runtime_error("independent/fullstatecheck");printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":true,\"checked_values\":11032684,\"max_abs_error\":%.17g,\"max_rel_error\":%.17g,\"independent_gate_max_abs\":%.17g,\"timing_region\":\"sum3_full_source_RushLarsen_timestepping_context_completion\",\"jit_excluded\":true,\"internal_repeats\":201,\"readonly_parameters_checked_count\":5315370,\"first_step_evidence\":\"untimed_replay_after_capturing_timed_final\",\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":11032684,\"byte_order\":\"little\"}}\n",trial,sec,metrics[0],metrics[1],metrics[2],path.c_str());}for(auto&d:ds){CK(cudaFree(d.rs));CK(cudaFree(d.rp));}return 0;}catch(std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
